n = int(input())
if n <= 1:
    print("Not Prime")
else:
    is_prime = True
    d = 2
    while d * d <= n:
        if n % d == 0:
            is_prime = False
            break
        d += 1
    print("Prime" if is_prime else "Not Prime")

